#include <iostream>
#include <algorithm>

using namespace std;

int fibonacci(int n) {
    // Base cases
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return 1;
    }
    // Recursive case
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    int n;
    cout << "Enter a positive integer n: ";
    cin >> n;

    int result = fibonacci(n);
    cout << "The nth Fibonacci number is: " << result << endl;

    return 0;
}

